using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class MyTools
{
    [McpServerTool, Description("Echoes the input message back to the caller.")]
    public static string Echo(string message) => $"Echo: {message}";

    [McpServerTool, Description("Adds two numbers together.")]
    public static double Add(double a, double b) => a + b;
}

using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "AppSettings",
        Title = "Application Settings", MimeType = "application/json")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { EnableCache = true, EnableLogging = true }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/environment", Name = "Environment",
        Title = "Environment Info", MimeType = "application/json")]
    public static string GetEnvironmentInfo()
    {
        var info = new
        {
            MachineName = Environment.MachineName,
            OsVersion = Environment.OSVersion.ToString(),
            Runtime = Environment.Version.ToString(),
            ProcessorCount = Environment.ProcessorCount
        };

        return JsonSerializer.Serialize(info, new JsonSerializerOptions { WriteIndented = true });
    }
}

